    case 18: /* SQL_BUFFER_RESULT */
    case 19: /* SQL_CALC_FOUND_ROWS */
    case 20: /* SQL_SMALL_RESULT */
    case 21: /* STRAIGHT_JOIN */
    case 22: /* CREATE */
    case 23: /* AGGREGATE */
    case 24: /* FUNCTION */
    case 25: /* INDEX */
    case 26: /* ON */
    case 27: /* LOGFILE */
    case 28: /* RESOURCE */
    case 29: /* SPATIAL */
    case 30: /* SERVER */
    case 31: /* TABLESPACE */
    case 32: /* UNDO */
    case 33: /* ROLE */
    case 34: /* USER */
    case 35: /* VIEW */
    case 36: /* EVENT */
    case 37: /* TRIGGER */
    case 38: /* UNIQUE */
    case 39: /* FULLTEXT */
    case 40: /* USING */
    case 41: /* TABLE */
    case 42: /* TEMPORARY */
    case 43: /* DATABASE */
    case 44: /* SCHEMA */
    case 45: /* PROCEDURE */
    case 46: /* OR */
    case 47: /* REPLACE */
    case 48: /* ALGORITHM */
    case 49: /* SQL */
    case 50: /* SECURITY */
    case 51: /* DEFINER */
    case 52: /* LP */
    case 53: /* RP */
    case 54: /* IF */
    case 55: /* DATA */
    case 56: /* COMMA */
    case 57: /* LB */
    case 58: /* RB */
    case 59: /* LC */
    case 60: /* RC */
    case 61: /* DROP */
    case 62: /* PREPARE */
    case 63: /* TABLES */
    case 64: /* MASTER */
    case 65: /* RESTRICT */
    case 66: /* CASCADE */
    case 67: /* ENGINE */
    case 68: /* ALTER */
